cssCode:
.layer-card-wrap {
  perspective: 1000px;
  width: 250px; height: 350px;
}
.layer-card {
  width: 100%; height: 100%;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 0.2s ease-out;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255,255,255,0.1);
  box-shadow: 0 20px 40px rgba(0,0,0,0.5);
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
}
.layer {
  position: absolute;
  border-radius: 15px;
  display: flex; align-items: center; justify-content: center;
  font-family: sans-serif; font-weight: bold;
  transition: transform 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
.layer-1 { width: 80%; height: 80%; background: #6c63ff; color: #fff; transform: translateZ(30px); }
.layer-2 { width: 60%; height: 40%; background: #00ffcc; color: #000; transform: translateZ(60px); box-shadow: 0 10px 20px rgba(0,0,0,0.3); }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'layer-card-wrap';

const card = document.createElement('div');
card.className = 'layer-card';

const l1 = document.createElement('div');
l1.className = 'layer layer-1';
l1.innerText = 'BACKGROUND';

const l2 = document.createElement('div');
l2.className = 'layer layer-2';
l2.innerText = 'FRONT';

card.appendChild(l1);
card.appendChild(l2);
wrap.appendChild(card);
c.appendChild(wrap);

wrap.addEventListener('pointermove', (e) => {
  const rect = wrap.getBoundingClientRect();
  const x = e.clientX - rect.left - rect.width / 2;
  const y = e.clientY - rect.top - rect.height / 2;
  card.style.transform = `rotateX(${-y * 0.15}deg) rotateY(${x * 0.15}deg)`;
});
wrap.addEventListener('pointerleave', () => {
  card.style.transform = `rotateX(0deg) rotateY(0deg)`;
});
